(939921, 109756, 18552, '<td valign="top">Wow! Great picture. This looks like my part of Colorado.</td>', 'Wow! Great picture. This looks like my part of Colorado.', '2004-10-04 03:23:12.000000', NULL, 1),
(939925, 109604, 16385, '<td valign="top">This is great<br/>10</td>', 'This is great10', '2004-10-04 03:25:08.000000', NULL, 1),
(939926, 109605, 1845, '<td valign="top">My first observation is that selective desat has been used to accentuate the colours of the bird.  My second observation is there is an ever so slight amount of motion blur and/or bird movement.  I would have hoped that a bird of such colour would do well on its own to stand out against bleak bark.  I don''t use a voting system that adds points for this or subtracts points for that; I sort of just let the mouse click where it may, guided mostly by my gut.  On the grand scheme of wildlife photography, bird images in particular, and this challenge especially, this is an average photo so I probably wouldn''t give it higher than 6 (and probably a 5).  Since I don''t think these numbers mean anything, I''m giving you a multidigit score (a non-degenerative one).</td>', 'My first observation is that selective desat has been used to accentuate the colours of the bird.  My second observation is there is an ever so slight amount of motion blur and/or bird movement.  I would have hoped that a bird of such colour would do well on its own to stand out against bleak bark.  I don''t use a voting system that adds points for this or subtracts points for that; I sort of just let the mouse click where it may, guided mostly by my gut.  On the grand scheme of wildlife photography, bird images in particular, and this challenge especially, this is an average photo so I probably wouldn''t give it higher than 6 (and probably a 5).  Since I don''t think these numbers mean anything, I''m giving you a multidigit score (a non-degenerative one).', '2004-10-04 03:25:36.000000', NULL, 1),
(939933, 109604, 26756, '<td valign="top">Absolutely love it!  Great subject ( what a little Prince! ), perfect composition, wonderful focus and detail and stunning color.  Congratulations!</td>', 'Absolutely love it!  Great subject ( what a little Prince! ), perfect composition, wonderful focus and detail and stunning color.  Congratulations!', '2004-10-04 03:34:16.000000', NULL, 1),
