(940319, 109744, 16493, '<td valign="top">very funny picture, wish the shadow we a bit less.</td>', 'very funny picture, wish the shadow we a bit less.', '2004-10-04 09:55:05.000000', NULL, 1),
(940320, 109002, 6008, '<td valign="top">What a face! This guy shows a lot of character, which is the one thing that makes images like this stand out. The composition is excellent and makes great use of the golden light. The side lighting put some of the majesty back into his straggly-looking face. Exposure looks good, it''s sharp where appropriate, nice clear eyes,  and has good texture in his fur. Excellent shot!</td>', 'What a face! This guy shows a lot of character, which is the one thing that makes images like this stand out. The composition is excellent and makes great use of the golden light. The side lighting put some of the majesty back into his straggly-looking face. Exposure looks good, it''s sharp where appropriate, nice clear eyes,  and has good texture in his fur. Excellent shot!', '2004-10-04 09:55:28.000000', NULL, 1),
