(940447, 109510, 26500, '<td valign="top">Great focus and interesting subject.  The lighting could have been a bit better.  Overall great work.</td>', 'Great focus and interesting subject.  The lighting could have been a bit better.  Overall great work.', '2004-10-04 11:06:27.000000', NULL, 1),
(940448, 109668, 26500, '<td valign="top">A different crop of this shot in a little better focus would have been perfect imo.  As it is, it is still a great shot with a well thought out title.</td>', 'A different crop of this shot in a little better focus would have been perfect imo.  As it is, it is still a great shot with a well thought out title.', '2004-10-04 11:07:27.000000', NULL, 1),
