(940921, 109670, 17033, '<td valign="top">Very nice idea and composition. Great light on head, too much on chest. Oversharpened perhaps</td>', 'Very nice idea and composition. Great light on head, too much on chest. Oversharpened perhaps', '2004-10-04 14:30:13.000000', NULL, 1),
(940922, 109552, 6008, '<td valign="top">I like the reflection and the ripple in the water. The tones are interesting, almost pastel except for the reeds/weeds/grass. The orange/yellow and black of the beak stands out nicely compared to the white of the swan. Exposure looks ok too.</td>', 'I like the reflection and the ripple in the water. The tones are interesting, almost pastel except for the reeds/weeds/grass. The orange/yellow and black of the beak stands out nicely compared to the white of the swan. Exposure looks ok too.', '2004-10-04 14:30:14.000000', NULL, 1),
