(942541, 109604, 2798, '<td valign="top">Great light, DoF and subject. Well done. 9 - floyd</td>', 'Great light, DoF and subject. Well done. 9 - floyd', '2004-10-05 07:53:55.000000', NULL, 1),
(942542, 109487, 15497, '<td valign="top">Very cool looking subject, you caught it in the exactly right time to produce a interesting image. Good luck 7</td>', 'Very cool looking subject, you caught it in the exactly right time to produce a interesting image. Good luck 7', '2004-10-05 07:54:05.000000', NULL, 1),
