(942545, 109797, 2798, '<td valign="top">Lovely visualisation of the picture. Shame about the light on your furry friend. 7 - floyd</td>', 'Lovely visualisation of the picture. Shame about the light on your furry friend. 7 - floyd', '2004-10-05 07:54:32.000000', NULL, 1),
(942546, 109307, 15497, '<td valign="top">Nice photo, difficult subject.. LOL</td>', 'Nice photo, difficult subject.. LOL', '2004-10-05 07:54:43.000000', NULL, 1),
