(942603, 109734, 19952, '<td valign="top">This is an absolutely beautiful photo. The focus seems just a little bit soft and it''s a tad overprocessed, but I love the water and the reflection. Really nice job.</td>', 'This is an absolutely beautiful photo. The focus seems just a little bit soft and it''s a tad overprocessed, but I love the water and the reflection. Really nice job.', '2004-10-05 08:22:14.000000', NULL, 1),
(942605, 109615, 19952, '<td valign="top">Great shot with excellent backlighting. It''s amazing you were able to get so much light on the subject with that much light behind it as well. The dirt on the paws and nose is a nice touch as well since it  shows what the animal was doing. Really nice job.</td>', 'Great shot with excellent backlighting. It''s amazing you were able to get so much light on the subject with that much light behind it as well. The dirt on the paws and nose is a nice touch as well since it  shows what the animal was doing. Really nice job.', '2004-10-05 08:24:26.000000', NULL, 1),
(942608, 109143, 19952, '<td valign="top">This is one of my favorite shots of this challenge. It''s a beautiful subject and you did a nice job of composition and capturing such outstanding detail. Great job.</td>', 'This is one of my favorite shots of this challenge. It''s a beautiful subject and you did a nice job of composition and capturing such outstanding detail. Great job.', '2004-10-05 08:27:09.000000', NULL, 1),
(942620, 109651, 19952, '<td valign="top">This is just a great shot - one of my favorite from this challenge. It seriously belongs in National Geographic or Alligator Fancy or something like that. :-) Really outstanding job.</td>', 'This is just a great shot - one of my favorite from this challenge. It seriously belongs in National Geographic or Alligator Fancy or something like that. :-) Really outstanding job.', '2004-10-05 08:43:38.000000', NULL, 1),
(942623, 109643, 19952, '<td valign="top">I really like this shot. Normally I prefer a fair amount of contrast between the subject and the background, but it''s so cool how the cat blends into the golden brown color of the wall. In addition, the composition and detail in the fur are outstanding. Really great job.</td>', 'I really like this shot. Normally I prefer a fair amount of contrast between the subject and the background, but it''s so cool how the cat blends into the golden brown color of the wall. In addition, the composition and detail in the fur are outstanding. Really great job.', '2004-10-05 08:48:03.000000', NULL, 1),
