(942891, 108557, 24846, '<td valign="top">Nice shot with him on the move. Like the crop on this 11 pointer.</td>', 'Nice shot with him on the move. Like the crop on this 11 pointer.', '2004-10-05 12:35:41.000000', NULL, 1),
(942895, 109295, 24846, '<td valign="top">Wow. I found the 10 for this challenge.. Can''t make this look any wilder, maybe with his maouth clamped on a camera. Can''t wait to see the details of this shot.  Great work...</td>', 'Wow. I found the 10 for this challenge.. Can''t make this look any wilder, maybe with his maouth clamped on a camera. Can''t wait to see the details of this shot.  Great work...', '2004-10-05 12:37:56.000000', NULL, 1),
(942899, 109436, 24846, '<td valign="top">Perfect composition.The background accents him well.</td>', 'Perfect composition.The background accents him well.', '2004-10-05 12:38:56.000000', NULL, 1),
