(949145, 109571, 19608, '<td valign="top">I like the sepia coloring but not the halo around the giraffe.</td>', 'I like the sepia coloring but not the halo around the giraffe.', '2004-10-07 22:04:40.000000', NULL, 1),
(949146, 108559, 19608, '<td valign="top">Exposure is perfect on this study of greens.  Good job.</td>', 'Exposure is perfect on this study of greens.  Good job.', '2004-10-07 22:05:35.000000', NULL, 1),
(949148, 108800, 19608, '<td valign="top">Very colorful.  Flat lighting helped a lot.</td>', 'Very colorful.  Flat lighting helped a lot.', '2004-10-07 22:06:48.000000', NULL, 1),
(949150, 109308, 19608, '<td valign="top">The foreground bird is superb.  The colors are great.  I wish the top of the foreground bird''s neck did not merge with the body behind.</td>', 'The foreground bird is superb.  The colors are great.  I wish the top of the foreground bird''s neck did not merge with the body behind.', '2004-10-07 22:08:41.000000', NULL, 1),
(949250, 109522, 18799, '<td valign="top">The challenge was specific about what was to be considered "wildlife"  Insects were not included in the list.</td>', 'The challenge was specific about what was to be considered "wildlife"  Insects were not included in the list.', '2004-10-07 23:03:27.000000', NULL, 1);
