(949259, 109800, 18799, '<td valign="top">I love the caption but it''s hardly like a box turtle to have an attitude ;)  7</td>', 'I love the caption but it''s hardly like a box turtle to have an attitude ;)  7', '2004-10-07 23:09:16.000000', NULL, 1),
(949262, 109347, 18799, '<td valign="top">Tough time of day for photography.  Lots of blown highlight and overly contrasty items. What is that blurr at 2 oclock to the fox?</td>', 'Tough time of day for photography.  Lots of blown highlight and overly contrasty items. What is that blurr at 2 oclock to the fox?', '2004-10-07 23:10:53.000000', NULL, 1),
(949264, 108434, 18799, '<td valign="top">I think it should have had a lot cropped from the left side.  The frog is way too centered.</td>', 'I think it should have had a lot cropped from the left side.  The frog is way too centered.', '2004-10-07 23:12:06.000000', NULL, 1),
(949267, 109788, 18799, '<td valign="top">Good potential, but it just doesn''t "pop".  Maybe some levels work in an editing program would help</td>', 'Good potential, but it just doesn''t "pop".  Maybe some levels work in an editing program would help', '2004-10-07 23:13:46.000000', NULL, 1),
(949269, 108890, 18799, '<td valign="top">Niice composition and great dof</td>', 'Niice composition and great dof', '2004-10-07 23:14:27.000000', NULL, 1),
(949272, 109333, 18799, '<td valign="top">Great expression, but focus needs to be better.</td>', 'Great expression, but focus needs to be better.', '2004-10-07 23:15:20.000000', NULL, 1),
(949277, 109373, 18799, '<td valign="top">Very contrasty.  Probably a bad time of day for photography, it looks like the Sun is at it''s strongest</td>', 'Very contrasty.  Probably a bad time of day for photography, it looks like the Sun is at it''s strongest', '2004-10-07 23:17:00.000000', NULL, 1),
(949283, 109043, 18799, '<td valign="top">Good exposure, focus, depth of field, but I''m afraid his pose is boring.</td>', 'Good exposure, focus, depth of field, but I''m afraid his pose is boring.', '2004-10-07 23:19:07.000000', NULL, 1),
(949286, 109797, 18799, '<td valign="top">excellent compostion!</td>', 'excellent compostion!', '2004-10-07 23:19:44.000000', NULL, 1),
(949294, 109511, 18799, '<td valign="top">Is hanging from a hook considered natural habitat?  Sorry, not in my book.  The photo itself isn''t bad though.  I would have liked to have seen more room at the top -but maybe that wasn''t possible.   I am voting this low because in my view, it doesn''t meet the intent of the challenge.  (plus fish are not in the list of what was to be considered to be wildlife)</td>', 'Is hanging from a hook considered natural habitat?  Sorry, not in my book.  The photo itself isn''t bad though.  I would have liked to have seen more room at the top -but maybe that wasn''t possible.   I am voting this low because in my view, it doesn''t meet the intent of the challenge.  (plus fish are not in the list of what was to be considered to be wildlife)', '2004-10-07 23:22:58.000000', NULL, 1),
(949302, 109593, 18799, '<td valign="top">The rain or mist really makes this a nice photo.  The light from below gives it a different feel.  Good job!</td>', 'The rain or mist really makes this a nice photo.  The light from below gives it a different feel.  Good job!', '2004-10-07 23:25:15.000000', NULL, 1),
(949307, 109591, 18799, '<td valign="top">It looks to be a little over the top in the saturation department.</td>', 'It looks to be a little over the top in the saturation department.', '2004-10-07 23:26:25.000000', NULL, 1),
(949311, 108189, 18799, '<td valign="top">Nice shot.  I would have liked it better if it wasn''t so centered in the frame</td>', 'Nice shot.  I would have liked it better if it wasn''t so centered in the frame', '2004-10-07 23:27:08.000000', NULL, 1),
(949314, 108672, 18799, '<td valign="top">I''m not an expert on snails, but I''m pretty sure a guitar is not natural habitat</td>', 'I''m not an expert on snails, but I''m pretty sure a guitar is not natural habitat', '2004-10-07 23:27:55.000000', NULL, 1),
