(949325, 109307, 18799, '<td valign="top">A little out of focus.</td>', 'A little out of focus.', '2004-10-07 23:31:04.000000', NULL, 1),
(949335, 109462, 18799, '<td valign="top">Nice shot, and nice choice of sepia tones.  The photo looks like it was over processed as there is a halo around all the edges.  I have to mark it down a point for that.</td>', 'Nice shot, and nice choice of sepia tones.  The photo looks like it was over processed as there is a halo around all the edges.  I have to mark it down a point for that.', '2004-10-07 23:33:17.000000', NULL, 1),
