INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(967189, 109522, 21124, '<td valign="top">Original picture:<br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=114346" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/21124/thumb/114346.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/21124/thumb/114346.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/21124/thumb/114346.jpg"/></a></td>', 'Original picture:', '2004-10-20 17:16:18.000000', NULL, 0),
(967756, 109787, 17203, '<td valign="top">A good shot, resulting in a good score. I''d give it a 6. The red color in the mouth is the highlight of the image. So why didn''t it top 6? There are no major problems, but an accumulation of little details cost you about half a point...<br/> <br/>Shooting a ''common'' animal automatically puts you at a disadvantage ribbon-wise. Sure, it''s do-able, but your focus has to be razor sharp, and you need a great expression and/or beautiful light (look at the cat shots in my favorites).<br/> <br/>It looks like you shot this on a cloudy day, so you pushed the ISO a little higher to compensate for the low light. Fair enough, but the lighting is still kinda'' flat, and the higher ISO yields grain in the background. Your focus is decent, but the only crisp detail is just above the right leg- maybe you had to crop a lot, didn''t use a tripod or didn''t use Bicubic Sharper when scaling down. With advanced editing, you certainly could have cleaned up the spot on the railing. Lastly (and probably most importantly) the seagull has it''s mouth open, but that''s about it- the expression is still rather blank, and the centered composition is completely static. If you couldn''t get another shot, you could burn and dodge some subtle shading around the eye for a "meaner" expression, and maybe a diagonal or off-centered crop would make the image more dynamic.</td>', 'A good shot, resulting in a good score. I''d give it a 6. The red color in the mouth is the highlight of the image. So why didn''t it top 6? There are no major problems, but an accumulation of little details cost you about half a point... Shooting a ''common'' animal automatically puts you at a disadvantage ribbon-wise. Sure, it''s do-able, but your focus has to be razor sharp, and you need a great expression and/or beautiful light (look at the cat shots in my favorites). It looks like you shot this on a cloudy day, so you pushed the ISO a little higher to compensate for the low light. Fair enough, but the lighting is still kinda'' flat, and the higher ISO yields grain in the background. Your focus is decent, but the only crisp detail is just above the right leg- maybe you had to crop a lot, didn''t use a tripod or didn''t use Bicubic Sharper when scaling down. With advanced editing, you certainly could have cleaned up the spot on the railing. Lastly (and probably most importantly) the seagull has it''s mouth open, but that''s about it- the expression is still rather blank, and the centered composition is completely static. If you couldn''t get another shot, you could burn and dodge some subtle shading around the eye for a "meaner" expression, and maybe a diagonal or off-centered crop would make the image more dynamic.', '2004-10-20 23:59:47.000000', NULL, 0),
